/**
 * Universal Runtime Environment Variable Reader for Vite SPA
 * 
 * Supports dual mechanism:
 * 1. K8s Pod Injection / Runtime Config (via window.__ENV generated by docker-entrypoint.sh)
 * 2. Physical .env file (fallback via import.meta.env)
 * 
 * Priority:
 * window.__ENV[key] (if present and non-empty) -> import.meta.env[key] -> fallback
 * 
 * @param {string} key - Environment variable name (e.g. "VITE_API_URL")
 * @param {string} fallback - Fallback default value if not found
 * @returns {string} The resolved environment variable value
 */
export function getRuntimeEnv(key, fallback = '') {
  if (typeof window !== 'undefined' && window.__ENV && window.__ENV[key] !== undefined && window.__ENV[key] !== '') {
    return window.__ENV[key];
  }

  const importMetaVal = import.meta.env[key];
  if (importMetaVal !== undefined && importMetaVal !== '') {
    return importMetaVal;
  }

  return fallback;
}
